#include <algorithm>
#include <iostream>
#include <vector>
using namespace std;

using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll a, b;
    cin >> a >> b;

    vector<ll> path;
    path.push_back(b);

    while (b > a) {
        if (b % 10 == 1) {
            b /= 10;
        } else if (b % 2 == 0) {
            b /= 2;
        } else {
            break;
        }
        path.push_back(b);
    }

    if (b != a) {
        cout << "NO\n";
        return 0;
    }

    reverse(path.begin(), path.end());

    cout << "YES\n" << path.size() << '\n';
    for (size_t i = 0; i < path.size(); ++i) {
        if (i) cout << ' ';
        cout << path[i];
    }
    cout << '\n';

    return 0;
}

